-- ============================================================
-- 将 current 设备类型（含已整合的 FT 平台类型）写入 za_device_type
-- aliases: [{"pfCode":"ft","alias":"<FT code>"}]
-- 以 code 为唯一键：已存在则更新名称与 aliases，不存在则插入。
-- ============================================================

ON DUPLICATE KEY UPDATE name = VALUES(name), aliases = VALUES(aliases), status = VALUES(status), remark = VALUES(remark), update_time = NOW();
